appsmith.onReady(function () {
  var navMenu = document.getElementById('navMenu');
  function decodeB64(s) {
    if (!s) {
      return null;
    }
    try {
      return JSON.parse(decodeURIComponent(escape(atob(s))));
    } catch (e) {
      return null;
    }
  }
  function esc(s) {
    var d = document.createElement('div');
    d.textContent = s == null ? '' : String(s);
    return d.innerHTML;
  }
  var PLAT_NAMES = {
    instagram: 'Instagram',
    tiktok: 'TikTok',
    facebook: 'Facebook',
    x: 'X (Twitter)',
    reddit: 'Reddit',
    threads: 'Threads',
    bluesky: 'Bluesky',
    snapchat: 'Snapchat',
    truth_social: 'Truth Social',
    youtube: 'YouTube',
    rumble: 'Rumble',
    twitch: 'Twitch',
    kwai: 'Kwai',
    kick: 'Kick',
    linkedin: 'LinkedIn',
    github: 'GitHub',
    telegram: 'Telegram',
    tiktok_shop: 'TikTok Shop',
    facebook_marketplace: 'FB Marketplace',
    facebook_events: 'FB Events',
    facebook_ad_library: 'FB Ad Library',
    tiktok_ad_library: 'TikTok Ad Library',
    google_ad_library: 'Google Ad Library',
    linkedin_ad_library: 'LinkedIn Ad Library',
    spotify: 'Spotify',
    apple_music: 'Apple Music',
    soundcloud: 'SoundCloud',
    google: 'Google',
    pinterest: 'Pinterest'
  };
  var PLAT_COLORS = {
    instagram: '#2E9BCB',
    tiktok: '#2F323B',
    facebook: '#2972A9',
    x: '#2F323B',
    reddit: '#585A61',
    threads: '#585A61',
    bluesky: '#2E9BCB',
    snapchat: '#2972A9',
    truth_social: '#585A61',
    youtube: '#2972A9',
    rumble: '#585A61',
    twitch: '#2E9BCB',
    kwai: '#2972A9',
    kick: '#585A61',
    linkedin: '#2972A9',
    github: '#2F323B',
    telegram: '#2E9BCB',
    tiktok_shop: '#585A61',
    facebook_marketplace: '#2972A9',
    facebook_events: '#2E9BCB',
    facebook_ad_library: '#2972A9',
    tiktok_ad_library: '#2E9BCB',
    google_ad_library: '#2972A9',
    linkedin_ad_library: '#2F323B',
    spotify: '#585A61',
    apple_music: '#2E9BCB',
    soundcloud: '#2972A9',
    google: '#585A61',
    pinterest: '#2F323B'
  };
  function platName(code) {
    return PLAT_NAMES[code] || code;
  }
  function platColor(code) {
    return PLAT_COLORS[code] || '#2972A9';
  }
  var role = 'viewer';
  try {
    var model = appsmith.model || {};
    role = model.userRole || 'viewer';
    var email = model.userEmail || '';
    var active = model.active || 'dashboard';
    document.getElementById('userEmail').textContent = email;
    document.getElementById('userRole').textContent = role.toUpperCase();
    document.getElementById('userAvatar').textContent = email.charAt(0).toUpperCase() || 'A';
    var MENU = [{
      section: 'Análisis',
      items: [{
        id: 'dashboard',
        label: 'Dashboard',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'mentions',
        label: 'Menciones',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'analytics',
        label: 'Analítica',
        roles: ['admin', 'analyst']
      }, {
        id: 'competitors',
        label: 'Competencia',
        roles: ['admin', 'analyst']
      }]
    }, {
      section: 'Gestión',
      items: [{
        id: 'targets',
        label: 'Objetivos',
        roles: ['admin', 'analyst']
      }, {
        id: 'alerts',
        label: 'Alertas',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'reports',
        label: 'Reportes',
        roles: ['admin', 'analyst', 'viewer']
      }]
    }, {
      section: 'Administración',
      items: [{
        id: 'tasks',
        label: 'Tareas de Scrapeo',
        roles: ['admin']
      }, {
        id: 'integrations',
        label: 'Integraciones',
        roles: ['admin']
      }, {
        id: 'users',
        label: 'Usuarios',
        roles: ['admin']
      }, {
        id: 'roles',
        label: 'Roles y Permisos',
        roles: ['admin']
      }, {
        id: 'audit',
        label: 'Auditoría',
        roles: ['admin']
      }, {
        id: 'settings',
        label: 'Configuración',
        roles: ['admin']
      }, {
        id: 'billing',
        label: 'Plan y Suscripción',
        roles: ['admin']
      }]
    }];
    var TITLES = {
      dashboard: 'Dashboard Ejecutivo',
      mentions: 'Menciones',
      analytics: 'Analítica',
      competitors: 'Competencia',
      targets: 'Objetivos Monitoreados',
      alerts: 'Alertas',
      reports: 'Reportes',
      tasks: 'Tareas de Scrapeo',
      integrations: 'Integraciones',
      users: 'Usuarios',
      roles: 'Roles y Permisos',
      audit: 'Auditoría',
      settings: 'Configuración',
      billing: 'Plan y Suscripción'
    };
    navMenu.innerHTML = '';
    MENU.forEach(function (section) {
      var visible = [];
      for (var i = 0; i < section.items.length; i++) {
        if (section.items[i].roles.indexOf(role) !== -1) {
          visible.push(section.items[i]);
        }
      }
      if (visible.length === 0) {
        return;
      }
      var containsActive = false;
      for (var j = 0; j < visible.length; j++) {
        if (visible[j].id === active) {
          containsActive = true;
        }
      }
      var group = document.createElement('li');
      group.className = 'nav-group' + (containsActive ? '' : ' collapsed');
      var head = document.createElement('div');
      head.className = 'nav-section-head';
      var headLabel = document.createElement('span');
      headLabel.textContent = section.section;
      head.appendChild(headLabel);
      head.addEventListener('click', function () {
        if (group.classList.contains('collapsed')) {
          group.classList.remove('collapsed');
        } else {
          group.classList.add('collapsed');
        }
      });
      group.appendChild(head);
      var list = document.createElement('ul');
      list.className = 'nav-group-items';
      visible.forEach(function (item) {
        var li = document.createElement('li');
        li.className = 'nav-item' + (item.id === active ? ' active' : '');
        li.textContent = item.label;
        li.addEventListener('click', function () {
          appsmith.triggerEvent('go_' + item.id);
        });
        list.appendChild(li);
      });
      group.appendChild(list);
      navMenu.appendChild(group);
    });
    document.getElementById('viewTitle').textContent = TITLES[active] || 'Dashboard Ejecutivo';
    document.getElementById('logoutBtn').addEventListener('click', function () {
      appsmith.triggerEvent('onLogout');
    });
  } catch (errShell) {
    navMenu.innerHTML = '<li style="color:#A7CDDE;padding:12px;font-size:11px;">ERROR SHELL: ' + errShell.message + '</li>';
    return;
  }
  if ((appsmith.model || {}).active === 'dashboard') {
    try {
      initDashboardModule();
    } catch (errMod) {
      var area = document.getElementById('contentArea');
      if (area) {
        area.innerHTML = '<div style="color:#2F323B;background:rgba(167,205,222,0.18);border:1px solid rgba(167,205,222,0.65);border-radius:10px;padding:14px;font-size:12px;">ERROR MODULO: ' + errMod.message + '</div>';
      }
    }
  }
  function renderDash(data) {
    var area = document.getElementById('contentArea');
    if (!area) {
      return;
    }
    if (!data) {
      area.innerHTML = '<div class="empty-state">' + '<h4>Cargando métricas…</h4>' + '<p>El dashboard se poblará al recibir datos del pipeline.</p>' + '</div>';
      return;
    }
    var k = data.kpis || {};
    var daily = data.daily || [];
    var top = data.top || [];
    var platforms = data.platforms || [];
    var lastScrape = k.last_scrape ? String(k.last_scrape).slice(0, 16).replace('T', ' ') : '—';
    var platCards = '';
    platforms.forEach(function (p) {
      var ultimo = p.ultimo_post ? String(p.ultimo_post).slice(0, 10) : '—';
      platCards += '<div class="plat-card">' + '<span class="plat-badge" style="background:' + platColor(p.platform) + '">' + esc(platName(p.platform)) + '</span>' + '<div class="plat-stats">' + '<div class="plat-stat">' + '<span class="plat-stat-value">' + esc(p.posts) + '</span>' + '<span class="plat-stat-label">posts</span>' + '</div>' + '<div class="plat-stat">' + '<span class="plat-stat-value">' + esc(p.reacciones) + '</span>' + '<span class="plat-stat-label">reacciones</span>' + '</div>' + '<div class="plat-stat">' + '<span class="plat-stat-value">' + esc(p.comentarios) + '</span>' + '<span class="plat-stat-label">comentarios</span>' + '</div>' + '</div>' + '<span class="plat-last">último post: ' + esc(ultimo) + '</span>' + '</div>';
    });
    var maxR = 1;
    daily.forEach(function (d) {
      if (Number(d.reacciones) > maxR) {
        maxR = Number(d.reacciones);
      }
    });
    var bars = '';
    daily.forEach(function (d) {
      var h = Math.max(Math.round(Number(d.reacciones) / maxR * 100), 2);
      bars += '<div class="bar-col">' + '<div class="bar" style="height:' + h + '%" title="' + esc(d.dia) + ' — ' + esc(d.reacciones) + ' reacciones / ' + esc(d.posts) + ' posts">' + '</div>' + '<span class="bar-label">' + esc(d.dia) + '</span>' + '</div>';
    });
    var rows = '';
    top.forEach(function (t) {
      var txt = (t.content_text || '').replace(/\s+/g, ' ').slice(0, 90);
      if ((t.content_text || '').length > 90) {
        txt += '…';
      }
      rows += '<tr>' + '<td>' + '<span class="plat-badge" style="background:' + platColor(t.platform) + '">' + esc(platName(t.platform)) + '</span>' + '</td>' + '<td class="cell-strong">' + esc(txt) + '</td>' + '<td>' + esc(t.reacciones) + '</td>' + '<td>' + esc(t.comentarios) + '</td>' + '<td class="cell-muted">' + esc(t.published_at ? String(t.published_at).slice(0, 10) : '') + '</td>' + '</tr>';
    });
    area.innerHTML = '<div class="kpi-grid">' + '<div class="kpi-card">' + '<span class="kpi-label">Publicaciones</span>' + '<span class="kpi-value">' + esc(k.total_posts || 0) + '</span>' + '<span class="kpi-sub">todas las plataformas</span>' + '</div>' + '<div class="kpi-card">' + '<span class="kpi-label">Reacciones</span>' + '<span class="kpi-value">' + esc(k.total_reactions || 0) + '</span>' + '<span class="kpi-sub">suma última medición</span>' + '</div>' + '<div class="kpi-card">' + '<span class="kpi-label">Comentarios</span>' + '<span class="kpi-value">' + esc(k.total_comments || 0) + '</span>' + '<span class="kpi-sub">suma última medición</span>' + '</div>' + '<div class="kpi-card">' + '<span class="kpi-label">Objetivos activos</span>' + '<span class="kpi-value">' + esc(k.total_targets || 0) + '</span>' + '<span class="kpi-sub">último scrape: ' + esc(lastScrape) + '</span>' + '</div>' + '</div>' + '<section class="table-panel">' + '<div class="panel-head">' + '<h3>Actividad por plataforma</h3>' + '</div>' + '<div class="plat-grid">' + (platCards || '<p style="font-size:12px;color:#585A61;">Sin plataformas con datos aún.</p>') + '</div>' + '</section>' + '<section class="table-panel">' + '<div class="panel-head">' + '<h3>Reacciones por día (todas las redes)</h3>' + '</div>' + '<div class="chart">' + (bars || '<p style="font-size:12px;color:#585A61;">Sin datos aún.</p>') + '</div>' + '</section>' + '<section class="table-panel">' + '<div class="panel-head">' + '<h3>Top publicaciones por reacciones</h3>' + '</div>' + '<table class="sl-table">' + '<thead>' + '<tr>' + '<th>Red</th>' + '<th>Contenido</th>' + '<th>Reacciones</th>' + '<th>Comentarios</th>' + '<th>Fecha</th>' + '</tr>' + '</thead>' + '<tbody>' + (rows || '<tr>' + '<td colspan="5" class="cell-muted">Sin datos aún.</td>' + '</tr>') + '</tbody>' + '</table>' + '</section>';
  }
  function initDashboardModule() {
    renderDash(decodeB64(appsmith.model.dashJson));
    var last = appsmith.model.dashJson || '';
    function refresh() {
      var now = appsmith.model.dashJson || '';
      if (now !== last) {
        last = now;
        renderDash(decodeB64(now));
      }
    }
    if (typeof appsmith.onModelChange === 'function') {
      appsmith.onModelChange(refresh);
    } else {
      setInterval(refresh, 1500);
    }
    setTimeout(function () {
      appsmith.triggerEvent('onLoadData');
    }, 300);
  }
