  padding: 0;
  box-sizing: border-box;
}

.sl-app {
  --ink: #2F323B;
  --paper: #FEFEFE;
  --card: #FFFFFF;
  --line: #A7CDDE;
  --line-soft: rgba(167, 205, 222, 0.45);
  --text: #2F323B;
  --muted: #585A61;
  --gold: #2972A9;
  --gold-bright: #2E9BCB;
  --gold-soft: rgba(46, 155, 203, 0.12);
  --green: #2972A9;
  --green-soft: rgba(41, 114, 169, 0.08);
  --red: #585A61;
  --red-soft: rgba(167, 205, 222, 0.18);

  display: flex;
  height: 100vh;
  background: var(--paper);
  color: var(--text);
  font-family: 'Inter', sans-serif;
}

.sidebar {
  width: 250px;
  background: var(--ink);
  color: #FEFEFE;
  display: flex;
  flex-direction: column;
}

.brand-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 22px 20px;
  border-bottom: 1px solid rgba(254, 254, 254, 0.08);
}

.brand-logo {
  width: 40px;
  height: 40px;
  display: block;
  object-fit: contain;
  border-radius: 11px;
  flex-shrink: 0;
}

.brand-text {
  display: flex;
  flex-direction: column;
}

.brand-name {
  font-family: 'Playfair Display', serif;
  font-size: 15px;
  font-weight: 700;
}

.brand-tag {
  font-size: 9px;
  color: var(--gold-bright);
  text-transform: uppercase;
  letter-spacing: 0.14em;
  margin-top: 2px;
}

.nav-menu {
  list-style: none;
  padding: 12px 12px;
  flex: 1;
  overflow-y: auto;
}

.nav-group {
  margin-bottom: 6px;
}

.nav-section-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px 6px;
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(254, 254, 254, 0.35);
  cursor: pointer;
  user-select: none;
  transition: color 0.2s;
}

.nav-section-head:hover {
  color: rgba(254, 254, 254, 0.65);
}

.nav-section-head::after {
  content: '';
  width: 7px;
  height: 7px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: rotate(45deg);
  transition: transform 0.2s;
}

.nav-group.collapsed .nav-section-head::after {
  transform: rotate(-45deg);
}

.nav-group-items {
  list-style: none;
}

.nav-group.collapsed .nav-group-items {
  display: none;
}

.nav-item {
  position: relative;
  padding: 10px 14px;
  margin-bottom: 3px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
  color: rgba(254, 254, 254, 0.60);
  transition: all 0.2s;
}

.nav-item:hover {
  background: rgba(46, 155, 203, 0.10);
  color: #FEFEFE;
}

.nav-item.active {
  background: linear-gradient(
    90deg,
    rgba(46, 155, 203, 0.20),
    rgba(41, 114, 169, 0.04)
  );
  color: var(--gold-bright);
}

.nav-item.active::before {
  content: '';
  position: absolute;
  left: 0;
  top: 22%;
  height: 56%;
  width: 3px;
  border-radius: 3px;
  background: var(--gold-bright);
}

.sidebar-footer {
  padding: 14px;
  border-top: 1px solid rgba(254, 254, 254, 0.08);
}

.logout-btn {
  width: 100%;
  padding: 10px;
  background: transparent;
  border: 1px solid rgba(167, 205, 222, 0.22);
  border-radius: 8px;
  color: rgba(254, 254, 254, 0.60);
  font-size: 12px;
  font-weight: 500;
  font-family: 'Inter', sans-serif;
  cursor: pointer;
  transition: all 0.2s;
}

.logout-btn:hover {
  border-color: var(--gold-bright);
  color: var(--gold-bright);
}

.main {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 18px 28px;
  border-bottom: 1px solid var(--line);
}

.topbar-kicker {
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--gold);
}

.topbar h2 {
  font-family: 'Playfair Display', serif;
  font-size: 22px;
  font-weight: 700;
  margin-top: 2px;
}

.user-chip {
