  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 700;
}

.user-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.user-info #userEmail {
  font-size: 12px;
  font-weight: 600;
}

.role-badge {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--gold-bright);
}

.content {
  flex: 1;
  padding: 26px 28px;
  overflow-y: auto;
}

.table-panel {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 22px;
  margin-bottom: 20px;
}

.panel-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
}

.panel-head h3 {
  font-family: 'Playfair Display', serif;
  font-size: 17px;
  font-weight: 700;
}

.sl-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.sl-table thead th {
  text-align: left;
  padding: 10px 12px;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
  border-bottom: 1px solid var(--line);
}

.sl-table tbody td {
  padding: 12px;
  border-bottom: 1px solid var(--line-soft);
}

.sl-table tbody tr:hover {
  background: rgba(167, 205, 222, 0.10);
}

.cell-strong {
  font-weight: 600;
}

.cell-muted {
  color: var(--muted);
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 50px 20px;
  text-align: center;
}

.empty-state h4 {
  font-family: 'Playfair Display', serif;
  font-size: 17px;
  margin-bottom: 6px;
}

.empty-state p {
  font-size: 12px;
  color: var(--muted);
  max-width: 340px;
  line-height: 1.7;
}

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 20px;
}

.kpi-card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.kpi-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.kpi-value {
  font-family: 'Playfair Display', serif;
  font-size: 30px;
  font-weight: 700;
  color: var(--green);
}

.kpi-sub {
  font-size: 10px;
  color: var(--gold-bright);
}

.plat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 16px;
}

.plat-card {
  background: rgba(167, 205, 222, 0.08);
  border: 1px solid var(--line-soft);
  border-radius: 12px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.plat-badge {
  display: inline-block;
  align-self: flex-start;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  color: #FFFFFF;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.plat-stats {
  display: flex;
  gap: 18px;
}

.plat-stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.plat-stat-value {
  font-family: 'Playfair Display', serif;
  font-size: 20px;
  font-weight: 700;
  color: var(--green);
}

.plat-stat-label {
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
}

.plat-last {
  font-size: 10px;
  color: var(--gold-bright);
}

.chart {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  height: 190px;
}

.bar-col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  height: 100%;
}

.bar {
  width: 100%;
  max-width: 46px;
  background: linear-gradient(
    180deg,
    var(--gold-bright),
    var(--green)
  );
  border-radius: 6px 6px 0 0;
  transition: height 0.4s;
}

.bar-label {
  font-size: 9px;
  color: var(--muted);
  margin-top: 6px;
}

