        '</div>' +
      '</section>' +

      '<section class="table-panel">' +
        '<div class="panel-head">' +
          '<h3>Top publicaciones por reacciones</h3>' +
        '</div>' +

        '<table class="sl-table">' +
          '<thead>' +
            '<tr>' +
              '<th>Red</th>' +
              '<th>Contenido</th>' +
              '<th>Reacciones</th>' +
              '<th>Comentarios</th>' +
              '<th>Fecha</th>' +
            '</tr>' +
          '</thead>' +

          '<tbody>' +
            (
              rows ||
              '<tr>' +
                '<td colspan="5" class="cell-muted">Sin datos aún.</td>' +
              '</tr>'
            ) +
          '</tbody>' +
        '</table>' +
      '</section>';
  }

  function initDashboardModule() {
    renderDash(
      decodeB64(appsmith.model.dashJson)
    );

    var last = appsmith.model.dashJson || '';

    function refresh() {
      var now = appsmith.model.dashJson || '';

      if (now !== last) {
        last = now;
        renderDash(
          decodeB64(now)
        );
      }
    }

    if (typeof appsmith.onModelChange === 'function') {
      appsmith.onModelChange(refresh);
    } else {
      setInterval(refresh, 1500);
    }

    setTimeout(function () {
      appsmith.triggerEvent('onLoadData');
    }, 300);
  }
});
